var cur='vi',cache={},pending={},obs=null,bq={},bt=null;
try{var c=localStorage.getItem('sao_tc');if(c)cache=JSON.parse(c);}catch(e){}
function svc(){try{var j=JSON.stringify(cache);if(j.length<5e6)localStorage.setItem('sao_tc',j);}catch(e){}}

function qfT(t,l){
 if(l==='vi'||l==='en')return;
 if(cache[l]&&cache[l][t]!==undefined)return;
 if(pending[l+'::'+t])return;
 if(!bq[l])bq[l]=[];
 if(bq[l].indexOf(t)===-1){bq[l].push(t);pending[l+'::'+t]=true;}
 if(!bt)bt=setTimeout(pb,300);
}
function pb(){
 bt=null;
 for(var l in bq){
  if(!bq[l].length)continue;
  var ts=bq[l].slice(0,10);bq[l]=bq[l].slice(10);
  tb(ts,l);
 }
 var hm=false;for(var l in bq){if(bq[l].length)hm=true;}
 if(hm)bt=setTimeout(pb,500);
}
function tb(ts,l){
 var gc=GCODE[l]||l;
 var ps=ts.map(function(t){
  return fetch('https://translate.googleapis.com/translate_a/single?client=gtx&sl=vi&tl='+encodeURIComponent(gc)+'&dt=t&q='+encodeURIComponent(t))
   .then(function(r){return r.json();})
   .then(function(d){var tr='';if(d&&d[0])tr=d[0].map(function(s){return s[0];}).join('');if(!cache[l])cache[l]={};cache[l][t]=tr||t;delete pending[l+'::'+t];return{t:t,tr:tr||t};})
   .catch(function(){delete pending[l+'::'+t];return{t:t,tr:t};});
 });
 Promise.all(ps).then(function(){svc();applyDOM(l);});
}

function setEl(el,tx){if(el.dataset.i18nHtml==='true')el.innerHTML=tx;else el.textContent=tx;}

function applyDOM(l){
 if(l==='vi'){
  document.querySelectorAll('[data-i18n]').forEach(function(el){if(el.dataset.i18nO)setEl(el,el.dataset.i18nO);});
  document.documentElement.lang='vi';return;
 }
 document.documentElement.lang=(l==='en'?'en':l);
 document.querySelectorAll('[data-i18n]').forEach(function(el){
  var ot=el.dataset.i18nO||el.textContent.trim();
  if(!el.dataset.i18nO)el.dataset.i18nO=ot;
  if(l==='en'){setEl(el,EN[ot]||ot);}
  else{var c=(cache[l]&&cache[l][ot])||null;if(c)setEl(el,c);else qfT(ot,l);}
 });
}

function sObs(){
 if(obs)return;
 obs=new MutationObserver(function(ms){
  var hn=false;ms.forEach(function(m){m.addedNodes.forEach(function(n){
   if(n.nodeType===1){if(n.hasAttribute&&n.hasAttribute('data-i18n'))hn=true;if(n.querySelectorAll&&n.querySelectorAll('[data-i18n]').length)hn=true;}
  });});
  if(hn&&cur!=='vi')applyDOM(cur);
 });
 obs.observe(document.body,{childList:true,subtree:true});
}

window.switchSAOLang=function(l){
 if(!LNG[l])l='vi';cur=l;
 if(history.pushState){var u=new URL(window.location);u.searchParams.set('lang',l);window.history.pushState({},'',u);}
 var e=new Date(Date.now()+365*864e5).toUTCString();
 document.cookie='sao_lang='+l+';expires='+e+';path=/;SameSite=Lax';
 applyDOM(l);
 var btn=document.querySelector('.lang-btn');
 if(btn)btn.innerHTML=(FLG[l]||'')+' '+(LNG[l]||'Language')+' ▾';
 document.querySelectorAll('.lang-option').forEach(function(el){el.classList.toggle('active',el.getAttribute('data-lang')===l);});
 var dd=document.getElementById('langDropdown');if(dd)dd.classList.remove('open');
};

function init(){
 var sl=null,cks=document.cookie.split('; ');
 for(var i=0;i<cks.length;i++){if(cks[i].startsWith('sao_lang=')){sl=cks[i].split('=')[1];break;}}
 var up=new URLSearchParams(window.location.search),ul=up.get('lang');
 if(ul&&LNG[ul])sl=ul;
 if(!sl||!LNG[sl])sl='vi';
 cur=sl;
 document.querySelectorAll('[data-i18n]').forEach(function(el){if(!el.dataset.i18nO)el.dataset.i18nO=el.textContent.trim();});
 if(sl!=='vi')applyDOM(sl);
